function bh_blog_topic($title) {
    $rules = [
        'لباسشویی'=>'ماشین لباسشویی','یخچال|فریزر'=>'یخچال و فریزر','جاروبرقی|جارو شارژی'=>'جاروبرقی و نظافت','سرخ‌کن|سرخکن'=>'سرخ‌کن بدون روغن','ظرفشویی|ظرفشویی'=>'ماشین ظرفشویی','اسپرسوساز'=>'اسپرسوساز','قهوه‌ساز|قهوه ساز|کپسول‌ساز'=>'قهوه‌ساز و نوشیدنی','مایکروویو|سولاردام'=>'مایکروویو و سولاردام','غذاساز|خردکن|مخلوط‌کن'=>'لوازم آماده‌سازی غذا','تلویزیون|رزولوشن'=>'تلویزیون و سرگرمی','چای‌ساز|کتری'=>'چای‌ساز و کتری برقی','اتو'=>'اتو و بخار','تهویه|تصفیه هوا|پنکه|کولر'=>'تهویه و هوای خانه','هود'=>'هود آشپزخانه','انرژی|مصرف برق'=>'مصرف انرژی','گارانتی|خدمات پس از فروش|مرجوعی'=>'خرید مطمئن و خدمات','مشخصات فنی|قیمت|برند|چک‌لیست|اندازه|تحویل|فروشنده'=>'راهنمای خرید عمومی'
    ];
    foreach ($rules as $pattern=>$topic) if (preg_match('/'.$pattern.'/u', $title)) return $topic;
    return 'راهنمای خرید لوازم خانگی';
}

