function bh_build_blog_content($title, $topic, $category) {
    $pack = bh_topic_pack($topic, $title);
    $html = '<p class="bh-article-lead">اگر برای «'.esc_html($title).'» دنبال یک جواب کوتاه و قابل اعتماد هستید، این راهنما برای تصمیم‌گیری واقعی نوشته شده است؛ از نیازسنجی و مقایسه مشخصات تا خرید، نصب و نگهداری را مرحله‌به‌مرحله بررسی می‌کنیم.</p>';
    $html .= '<div class="bh-article-takeaway"><strong>خلاصه کاربردی</strong><span>اول نیاز و فضای خانه را مشخص کنید، سپس مشخصات هم‌سطح را مقایسه کنید و هزینه استفاده و خدمات پس از فروش را کنار قیمت اولیه ببینید.</span></div>';
    $html .= '<h2>قبل از انتخاب چه چیزهایی را بررسی کنیم؟</h2><p>بهترین محصول برای هر خانه یکسان نیست. تعداد کاربران، دفعات استفاده، اندازه محل نصب، دسترسی به برق یا آب، میزان صدا و بودجه نگهداری را مشخص کنید. یک فهرست کوتاه از نیازهای ضروری و قابلیت‌های ترجیحی بنویسید تا در برابر تبلیغات یا تخفیف‌های لحظه‌ای تصمیم خود را تغییر ندهید.</p>';
    foreach ($pack as [$heading,$text]) $html .= '<h2>'.esc_html($heading).'</h2><p>'.esc_html($text).'</p>';
    $html .= '<h2>چطور دو مدل را منصفانه مقایسه کنیم؟</h2><p>دو یا سه مدل هم‌رده را در یک جدول قرار دهید و فقط ویژگی‌های هم‌نام را مقایسه کنید: ظرفیت، ابعاد، مصرف انرژی، سطح صدا، برنامه‌ها، اقلام همراه، گارانتی و هزینه نصب. تفاوت نسخه یا کد کامل مدل را نادیده نگیرید؛ یک پسوند کوچک می‌تواند امکانات یا بازار مقصد دستگاه را تغییر دهد.</p><div class="bh-article-compare"><div><strong>ضروری</strong><span>ظرفیت، ابعاد، مصرف و خدمات</span></div><div><strong>قابل مذاکره</strong><span>رنگ، ظاهر و برخی برنامه‌ها</span></div><div><strong>هشدار</strong><span>ادعای بدون عدد یا منبع مشخص</span></div></div>';
    $html .= '<h2>اشتباه‌هایی که هزینه خرید را بالا می‌برند</h2><ul><li>انتخاب ظرفیت یا اندازه بدون اندازه‌گیری محل نصب.</li><li>مقایسه قیمت دو مدل با مشخصات و گارانتی متفاوت.</li><li>خرید قابلیت‌هایی که در استفاده روزمره به کار نمی‌آیند.</li><li>نادیده گرفتن هزینه فیلتر، مواد مصرفی، نصب و تعمیر.</li><li>اعتماد به نام برند بدون بررسی مدل دقیق و تجربه کاربران.</li></ul>';
    $html .= '<h2>چک‌لیست نهایی قبل از پرداخت</h2><ol><li>مدل دقیق و مشخصات صفحه محصول را با بسته‌بندی تطبیق دهید.</li><li>ابعاد مسیر ورود و محل نصب را دوباره اندازه بگیرید.</li><li>موجودی، اصالت، گارانتی، هزینه ارسال و نصب را بپرسید.</li><li>شرایط مرجوعی و خدمات پس از فروش را مکتوب یا در صفحه رسمی بررسی کنید.</li><li>دفترچه راهنما و اقلام همراه را هنگام تحویل کنترل کنید.</li></ol>';
    $html .= '<h2>جمع‌بندی راهنمای '.esc_html($category).'</h2><p>انتخاب حرفه‌ای یعنی محصولی که با سبک زندگی، فضای خانه و هزینه استفاده شما هم‌خوان باشد؛ نه لزوماً گران‌ترین یا پرامکانات‌ترین مدل بازار. اطلاعات صفحه محصول را با نیاز واقعی خود تطبیق دهید و اگر بین دو گزینه مردد هستید، معیارهای ضروری را وزن بیشتری بدهید.</p>';
    $html .= '<h2>پرسش‌های متداول</h2><div class="bh-article-faq"><details><summary>آیا گران‌تر بودن یعنی انتخاب بهتر؟</summary><p>خیر. قیمت باید در کنار ظرفیت، کیفیت ساخت، خدمات و هزینه نگهداری بررسی شود. محصولی که قابلیت‌های بلااستفاده دارد لزوماً ارزش خرید بیشتری ندارد.</p></details><details><summary>چطور از درست بودن مشخصات مطمئن شویم؟</summary><p>کد کامل مدل را با دفترچه، صفحه رسمی سازنده و اطلاعات فروشگاه تطبیق دهید و برای موارد مبهم از فروشنده سؤال مشخص بپرسید.</p></details><details><summary>بعد از خرید چه کاری مهم‌تر است؟</summary><p>نصب صحیح، مطالعه دفترچه، ثبت گارانتی و اجرای برنامه نظافت دوره‌ای بیشترین اثر را روی عملکرد و طول عمر دستگاه دارند.</p></details></div>';
    return $html;
}

$posts = get_posts(['post_type'=>'post','post_status'=>'publish','posts_per_page'=>-1,'orderby'=>'ID','order'=>'ASC']);
$updated = 0; $skipped = 0;
foreach ($posts as $post) {
    if ($post->post_name === 'hello-world' || trim(wp_strip_all_tags($post->post_title)) === 'سلام دنیا!') { $skipped++; continue; }
    $title = trim($post->post_title);
    $topic = bh_blog_topic($title);
    $cats = get_the_category($post->ID);
    $category = $cats ? $cats[0]->name : $topic;
    $content = bh_build_blog_content($title, $topic, $category);
    $focus = trim(preg_replace('/[؛،,:؟].*$/u', '', $title));
    $description = 'راهنمای کامل '.mb_strtolower($title, 'UTF-8').'؛ بررسی معیارهای انتخاب، مقایسه مشخصات، نکات کاربردی، نگهداری و پرسش‌های متداول برای خرید آگاهانه.';
    wp_update_post(['ID'=>$post->ID,'post_content'=>$content,'post_excerpt'=>wp_trim_words(wp_strip_all_tags($content), 34, '…')]);
    update_post_meta($post->ID, '_bhc_seo_title', $title.' | راهنمای تخصصی بهاران هوم');
    update_post_meta($post->ID, '_bhc_seo_description', $description);
    update_post_meta($post->ID, '_bhc_focus_keyword', $focus);
    update_post_meta($post->ID, '_bhc_content_status', 'بازنویسی و بهینه‌سازی SEO انجام شد');
    $updated++;
    echo "reviewed={$post->ID} topic={$topic} chars=".mb_strlen(wp_strip_all_tags($content))."\n";
}
echo "updated={$updated} skipped={$skipped}\n";
